async function disconnect() {
  _readLoopStop = true;
  try { if (_reader) { await _reader.cancel(); _reader.releaseLock(); } } catch (e) {}
  try { if (_writer) { _writer.releaseLock(); } } catch (e) {}
  try { if (_port)   { await _port.close(); } } catch (e) {}
  _connected = false;
  sBus.publish('org:disconnected', {});
}

